const fixture_gray = "\xff\xd8\xff\xe0\x00\x10\x4a\x46\x49\x46\x00\x01\x01\x00\x00\x01\x00\x01\x00\x00\xff\xdb\x00\x43" ++ "\x00\x0d\x09\x0a\x0b\x0a\x08\x0d\x0b\x0a\x0b\x0e\x0e\x0d\x0f\x13\x20\x15\x13\x12\x12\x13\x27\x1c" ++ "\x1e\x17\x20\x2e\x29\x31\x30\x2e\x29\x2d\x2c\x33\x3a\x4a\x3e\x33\x36\x46\x37\x2c\x2d\x40\x57\x41" ++ "\x46\x4c\x4e\x52\x53\x52\x32\x3e\x5a\x61\x5a\x50\x60\x4a\x51\x52\x4f\xff\xc0\x00\x0b\x08\x00\x0d" ++ "\x00\x13\x01\x01\x11\x00\xff\xc4\x00\x1f\x00\x00\x01\x05\x01\x01\x01\x01\x01\x01\x00\x00\x00\x00" ++ "\x00\x00\x00\x00\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0a\x0b\xff\xc4\x00\xb5\x10\x00\x02\x01\x03" ++ "\x03\x02\x04\x03\x05\x05\x04\x04\x00\x00\x01\x7d\x01\x02\x03\x00\x04\x11\x05\x12\x21\x31\x41\x06" ++ "\x13\x51\x61\x07\x22\x71\x14\x32\x81\x91\xa1\x08\x23\x42\xb1\xc1\x15\x52\xd1\xf0\x24\x33\x62\x72" ++ "\x82\x09\x0a\x16\x17\x18\x19\x1a\x25\x26\x27\x28\x29\x2a\x34\x35\x36\x37\x38\x39\x3a\x43\x44\x45" ++ "\x46\x47\x48\x49\x4a\x53\x54\x55\x56\x57\x58\x59\x5a\x63\x64\x65\x66\x67\x68\x69\x6a\x73\x74\x75" ++ "\x76\x77\x78\x79\x7a\x83\x84\x85\x86\x87\x88\x89\x8a\x92\x93\x94\x95\x96\x97\x98\x99\x9a\xa2\xa3" ++ "\xa4\xa5\xa6\xa7\xa8\xa9\xaa\xb2\xb3\xb4\xb5\xb6\xb7\xb8\xb9\xba\xc2\xc3\xc4\xc5\xc6\xc7\xc8\xc9" ++ "\xca\xd2\xd3\xd4\xd5\xd6\xd7\xd8\xd9\xda\xe1\xe2\xe3\xe4\xe5\xe6\xe7\xe8\xe9\xea\xf1\xf2\xf3\xf4" ++ "\xf5\xf6\xf7\xf8\xf9\xfa\xff\xda\x00\x08\x01\x01\x00\x00\x3f\x00\x8e\xdd\x42\xc4\x29\xd7\x0a\x04" ++ "\x0c\xcc\x0e\xcf\x51\x54\x85\xd4\x4a\x30\x06\x71\xde\xae\x42\xbe\xe6\xad\xa2\x09\x61\x65\x7e\x57" ++ "\x3d\x2a\xd2\x69\xd6\xc5\x01\x31\xaf\xe5\x5f\xff\xd9";

test "jpeg decode matches libjpeg-turbo on embedded files" {
    // FNV-1a of cv2.imdecode's output (converted to RGB).
    const cases = [_]struct { bytes: []const u8, hash: u32, w: u32, h: u32, ch: u16 }{
        .{ .bytes = fixture_prog420_rst, .hash = 0xc205440c, .w = 19, .h = 13, .ch = 3 }, // progressive 4:2:0 with restarts
        .{ .bytes = fixture_base422, .hash = 0x6d1d76ef, .w = 19, .h = 13, .ch = 3 }, // baseline 4:2:2
        .{ .bytes = fixture_gray, .hash = 0xf4f7deaf, .w = 19, .h = 13, .ch = 1 }, // grayscale
    };
    for (cases) |cs| {
        var img = try decode(testing.allocator, cs.bytes, .{});
        defer img.deinit(testing.allocator);
        const im = img.as(u8).?;
        try testing.expectEqual(cs.w, im.width);
        try testing.expectEqual(cs.h, im.height);
        try testing.expectEqual(cs.ch, im.channels);
        try testing.expectEqual(cs.hash, std.hash.Fnv1a_32.hash(im.slice()));
        // Every prefix decodes or fails cleanly.
        for (0..cs.bytes.len) |n| {
            if (decode(testing.allocator, cs.bytes[0..n], .{})) |r| {
                var m = r;
                m.deinit(testing.allocator);
            } else |_| {}
        }
    }
}
